"""Task-local helper: locate SQLite database(s) in this folder and report schema.

Read-only inspection - no data is modified.
"""
import os
import sqlite3
import sys

DB_SUFFIXES = (".db", ".sqlite", ".sqlite3")


def find_databases(folder):
    candidates = []
    for name in sorted(os.listdir(folder)):
        full = os.path.join(folder, name)
        if os.path.isfile(full) and name.lower().endswith(DB_SUFFIXES):
            candidates.append(full)
    return candidates


def describe_db(path):
    print("=" * 70)
    print("DATABASE:", path, f"({os.path.getsize(path)} bytes)")
    print("=" * 70)
    try:
        uri = f"file:{path}?mode=ro"
        conn = sqlite3.connect(uri, uri=True)
    except sqlite3.Error as exc:
        print("  ! could not open:", exc)
        return
    try:
        cur = conn.cursor()
        tables = cur.execute(
            "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
        ).fetchall()
        if not tables:
            print("  (no tables found)")
            return
        for (table,) in tables:
            print(f"\nTABLE: {table}")
            try:
                cols = cur.execute(f'PRAGMA table_info("{table}")').fetchall()
                for cid, cname, ctype, notnull, dflt, pk in cols:
                    flags = []
                    if pk:
                        flags.append("PRIMARY KEY")
                    if notnull:
                        flags.append("NOT NULL")
                    if dflt is not None:
                        flags.append(f"DEFAULT {dflt}")
                    print(f"  - {cname}  {ctype}  {' '.join(flags)}".rstrip())
                count = cur.execute(f'SELECT COUNT(*) FROM "{table}"').fetchone()[0]
                print(f"  row count: {count}")
            except sqlite3.Error as exc:
                print("  ! error reading table:", exc)
    finally:
        conn.close()


def main():
    folder = os.getcwd()
    print("WORKING DIRECTORY:", folder)
    print("FILES:", ", ".join(sorted(os.listdir(folder))) or "(empty)")
    dbs = find_databases(folder)
    if not dbs:
        print("\nNo SQLite files found in this folder.")
        # Show any other non-python files to help the user point us at the DB.
        others = [
            name
            for name in sorted(os.listdir(folder))
            if os.path.isfile(name) and not name.endswith((".py", ".pyc", ".md"))
        ]
        if others:
            print("Other files present:", ", ".join(others))
        sys.exit(1)
    for path in dbs:
        describe_db(path)
    print("\nDone.")


if __name__ == "__main__":
    main()

